    "a": 0,
    "e": "【答案】A\n【解析】第一步找语境线索：空一后接“自身资源禀赋”，且与前文“因地制宜”呼应，需填“从实际出发”义的词；空二主语是“特色产业”，后文“百舸争流、千帆竞发”提示各自发挥长处。第二步辨析词语：立足指站在某种基础之上，“立足资源禀赋”是政策话语中的规范搭配；各展其长指各自发挥自身长处，与“宜农则农、宜工则工”的分工语境严丝合缝，故本题选A。依托侧重依靠凭借，搭配资源禀赋稍弱；百花齐放多形容文艺创作或方针局面，与“特色产业”搭配不当。凭借侧重依靠外力条件，齐头并进强调不分先后地同时前进，忽略了“各有分工”的语义。根据表述平实，与公文语体略有落差，并驾齐驱强调彼此不分高下，与“各展所长”的侧重点不同。三个干扰项均为近义表达，需靠搭配与语义侧重择优。"
