    "e": "【答案】A\n【解析】第一步找语境线索：横线前有“多年积累的教学经验”，后有“传授给”，核心是强调把积累的东西毫无保留地教给他人。第二步辨析词语：倾囊相授指把所有的知识、经验毫无保留地传授出去，与“多年积累的经验”“传授”形成完美呼应，故本题选A。循循善诱指善于有步骤地引导别人学习，侧重教学方法的耐心巧妙，未体现“毫无保留”的语义；耳提面命形容恳切地教导，多用于长辈对晚辈且带有严厉督促色彩，感情色彩与文段温情的语境不合；言传身教指既用言语教导又用行动示范，侧重“以身作则”，与“传授经验”的侧重点不同。四个成语都与教导有关、感情色彩积极，只能依据“毫无保留地传授”这一语境线索来分辨。"
