    "multi": "ABC",
    "e": "【答案】：ABC\n【解析】开放也是改革，以开放促改革、促发展是我国发展不断取得新成就的宝贵经验，A项表述正确。深化贸易投资领域体制机制改革，稳步扩大规则、规制、管理、标准等制度型开放，是高水平对外开放的重要标志，B项表述正确。扩大对最不发达国家单边开放，让发展中国家共享中国发展机遇，是我国推动构建人类命运共同体的务实举措，C项表述正确。D项表述错误，把构建更高水平开放型经济新体制的目标替换为以出口创汇为主要目标，并把顺差规模说成衡量开放水平的根本标准，与互利共赢的开放战略不符。综上，本题选ABC。"
