    "q": "亚太经合组织领导人非正式会议即将在深圳举行，作为东道主的中国把开放、创新、合作列为今年合作的优先方向。回望来路，亚太之所以能够成为全球增长最具活力的板块，靠的从来不是________的零和思维，而是________、互利共赢的务实合作。面向未来，各方更应携手做大合作蛋糕，让发展成果惠及区域各方。",
