    "e": "【答案】C\n【解析】第一步，分析语境。第一空对应“从种子到种子”，指的是生命由起点回到起点的完整过程，需要一个表示周而复始的词语；第二空所填词支配的对象是“参数”，需要一个表示核对、验证是否准确的词语。第二步，辨析词语。第一空，“循环”指事物周而复始地运动变化，与“从种子到种子”的生命闭环完全对应，且与“生命历程”搭配自然；“更替”侧重新旧事物替换、轮流更换，强调的是替换而非周而复始的闭环，与“从种子到种子”的语义指向不符，故“更替”不当。第二空，“校验”指核对并验证是否准确可靠，与“参数”是固定搭配，符合科学实验严谨求实的语境；“推敲”比喻斟酌字句、反复琢磨，多用于文章、词句、方案的斟酌，不能与“数以千计参数”搭配，故“推敲”不当。综合两空，“循环”与“校验”均成立，本题选C。"
