    "e": "【答案】B\n【解析】第一步，分析语境。空前有“靠的从来不是运动式整治的一时之功”作反向提示，空后又有“制度防线”“更可持续”作正向呼应，故所填词应表达长期坚持、持续用力方能见效之意，且与“一时之功”形成鲜明对照。第二步，辨析词语。“久久为功”强调要经过长时间的持续努力才能见到成效，既含有时间维度上的长久，又暗含功夫、力道上的累积，与“一时之功”构成最直接的反义对照，是官方表述中的高频规范搭配。“持之以恒”侧重长久坚持下去、不松懈，虽也有长期之意，但它强调的是态度上的不间断，缺少与“一时之功”相对照的“功到自然成”的语义厚度，力度稍逊。“一蹴而就”比喻事情轻而易举、一下子就能成功，与空前“不是……的一时之功”在逻辑上虽然构成反义，但它多用于否定句式，此处需填正向的肯定性词语，语法与语义均不适配。“一劳永逸”指辛苦一次把事情办好、以后就不再费力，同样与“持续完善”“更可持续”的长期性语境相悖。综合辨析，本题选B。"
