    "e": "【答案】A\n【解析】第一步，分析语境。第一空所填词与“从‘单向末梢’到‘循环网络’”构成搭配，表示路网形态层级的抬升；第二空所填词修饰“支撑”，强调对区域协调发展的托举作用。第二步，辨析词语。第一空，“升级”指由较低的等级或层次升到较高的等级或层次，与前文“从……到……”的层级抬升表述严丝合缝，也是相关部门介绍的原文表述；“跨越”指越过某个界限或阶段，侧重时间、空间的跨过，用来描述路网结构形态的变化不及“升级”贴切。第二空，“有力”指有力量、成效明显，与“支撑”是公文中的高频固定搭配，强调当下已经且能够持续发挥作用的托举力；“长效”指长期发挥作用，侧重机制、制度的持久性，通常说“长效机制”，直接修饰“支撑”的搭配习惯不如“有力”自然。综合两空，升级、有力均成立，本题选A。"
