    "e": "【答案】：ABC\n【解析】A项正确。习近平总书记强调要把积极老龄观、健康老龄化理念融入经济社会发展全过程，这是做好新时代老龄工作的重要理念指引。B项正确。老年是仍然可以有作为、有进步、有快乐的重要人生阶段，要研究完善政策措施，鼓励老年人继续发光发热，努力实现老有所养、老有所为、老有所乐。C项正确。把弘扬孝亲敬老纳入社会主义核心价值观宣传教育，建设具有民族特色、时代特征的孝亲敬老文化，是习近平总书记明确提出的部署要求。D项错误。我国养老服务体系的格局是居家社区机构相协调、医养康养相结合，家庭在养老中承担着重要责任，把重心从居家社区转向机构集中供养并压缩家庭照护政策支持，属于主次关系错位。故本题选ABC。"
