    "e": "【答案】：C\n【解析】A项错误。我国调水工程坚持先节水后调水，先调水后节水会把调水当成万能钥匙，颠倒了节水优先的顺序。B项错误。正确表述是先环保后用水，把“先环保后用水”写成“先用后环保”属于顺序倒置。C项正确。我国推进南水北调等跨流域调水工程必须坚持先节水后调水、先治污后通水、先环保后用水的基本原则，把节水作为前提、治污作为关键、生态作为底线。D项错误。治污与通水的先后顺序是先治污后通水，把环保置于治污之前、通水置于用水之前，属于环节错位。故本题选C。"
