    "q": "长征这一气壮山河的英雄史诗，早已镌刻在中国革命的丰碑之上。回望那段苦难辉煌，红军将士在枪林弹雨中向死而生，在生存极限中绝境求生，靠的是信念如磐、意志如钢。今天，我们重温这段历史，不是为了____在过往的荣光里，而是要从伟大长征精神中____奋进的力量；新征程是充满光荣和梦想的远征，唯有接续奋斗、砥砺前行，才能把革命前辈开创的伟大事业不断推向前进。",
