    "e": "【答案】：A\n【解析】A项正确。规划坚守传播党的声音、服务人民群众的初心使命，坚持广播电视和网络视听两大业务深度融合、协同发展，把握意识形态、公共服务、技术产业三大属性，锚定巩固提升广播电视、创新发展网络视听、融合聚合形成合力三大工作方向。B项不符合题意。规划的三大属性是意识形态、公共服务、技术产业，把“技术产业”替换为“商业经营”，属于政治名词替换。C项不符合题意。规划统筹的是广播电视网、交互式网络电视、互联网电视和公众互联网四个业务层次，该选项漏掉“公众互联网”，属于漏条设错。D项不符合题意。规划推动的是两大业务深度融合、协同发展，而非把网络视听并入传统广播电视体系统一管理，属于偷换范围和方向。因此本题选A。"
