    "e": "【答案】：BCD\n【解析】B项正确。全球治理倡议旨在推动构建更加公正合理的全球治理体系，建设一个更加美好的世界，这是习近平主席在致信中明确阐明的倡议宗旨。C项正确。中国愿同各方一道践行共商共建共享的全球治理观，以信心汇聚力量、以合作破解难题，为变乱交织的世界注入更多确定性和正能量，携手迈向人类命运共同体。D项正确。全球治理倡议与全球发展倡议、全球安全倡议、全球文明倡议共同构成中国提出并带头践行的四大全球倡议，是推动构建人类命运共同体理念的重要支撑。A项错误。中国坚定维护以联合国为核心的国际体系和以国际法为基础的国际秩序，反对以实力地位凌驾于国际规则之上、以单边行动替代多边协商，该表述与全球治理倡议的精神完全相反。因此本题选BCD。"
